const s = $('Risk Summary').first().json;
const f = $('Findings Summary').first().json;
const top = $('Top Risk Vendors').all().map(i => i.json).filter(v => v.id);
const esc = x => String(x == null ? '' : x).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e7eb"';
const rows = top.length
  ? top.map(v => '<tr><td ' + td + '>' + esc(v.legal_name) + '</td><td ' + td + '>' + esc(v.current_score ?? '-') +
      '</td><td ' + td + '>' + esc(v.current_risk ?? '-') + '</td><td ' + td + '>' + esc(v.open_findings) + '</td></tr>').join('')
  : '<tr><td ' + td + ' colspan="4">Sin proveedores de riesgo alto o crítico.</td></tr>';
const kpi = (label, val) => '<td style="padding:8px 14px;text-align:center"><div style="font-size:22px;font-weight:700">' +
  esc(val) + '</div><div style="font-size:12px;color:#6b7280">' + label + '</div></td>';
const html = '<div style="font-family:Arial,sans-serif;max-width:680px">' +
  '<h2>VRM — Resumen semanal</h2>' +
  '<h3>Proveedores por nivel de riesgo (' + esc(s.total) + ' activos)</h3>' +
  '<table><tr>' + kpi('Crítico', s.critical) + kpi('Alto', s.high) + kpi('Medio', s.medium) + kpi('Bajo', s.low) + kpi('Mínimo', s.minimal) + '</tr></table>' +
  '<h3>Hallazgos</h3>' +
  '<table><tr>' + kpi('Abiertos', f.open) + kpi('Críticos abiertos', f.critical_open) + kpi('Vencidos', f.overdue) +
  kpi('Nuevos (7d)', f.new_7d) + kpi('Cerrados (7d)', f.closed_7d) + '</tr></table>' +
  '<h3>Top proveedores de riesgo</h3>' +
  '<table style="border-collapse:collapse;width:100%"><tr style="text-align:left;background:#f3f4f6"><th ' + td + '>Proveedor</th><th ' + td +
  '>Score</th><th ' + td + '>Riesgo</th><th ' + td + '>Hallazgos abiertos</th></tr>' + rows + '</table></div>';
return [{ json: { html } }];
